    // order: there a grouping would not mean anything.
    const sequence = interleave && quotaKey ? byGroupRounds(ordered, quotaKey) : ordered;
    const chosen = [];
    const decades = new Map();
    const quotas = new Map();
    for (const r of sequence) {
