#!/usr/bin/env node
/**
 * Add worldwide archival map records from two primary institutions to the seed.
 *
 * Why this script exists: the first seed was Swiss-first (e-rara + swisstopo).
 * The corrected product is a global atlas, so the archive list must also hold
 * real records from outside Switzerland. This script reads two documented,
 * machine-readable services directly and merges the result into the committed
 * seed (`public/data/records.json`, `public/data/sources.json`):
 *
 *   Library of Congress, Geography and Map Division
 *     discovery  https://www.loc.gov/maps/?q=<query>&fo=json   (documented JSON API)
 *     record     https://www.loc.gov/item/<lccn>/?fo=json
 *     image      https://tile.loc.gov/image-services/iiif/<imageId>…  (IIIF Image API 2)
 *     rights     free to use and reuse unless a rights advisory says otherwise
 *
 *   David Rumsey Map Collection (David Rumsey Map Center, Stanford University Libraries)
 *     discovery  https://www.davidrumsey.com/luna/servlet/as/search?q=<query>&os=0&bs=<n>
 *     record     https://www.davidrumsey.com/luna/servlet/detail/<id>
 *     image      https://www.davidrumsey.com/rumsey/Size2/<id path>.jpg (display derivative)
 *     rights     images CC BY-NC-SA 3.0; each record links to its own terms
 *
 * Two more candidates from the brief were probed and are *blocked* from this
 * runner (recorded in `worldHarvest.probes`, not silently dropped):
 *   BnF Gallica SRU      403 (bot challenge page), measured 2026-10-19
 *   National Library of Scotland 405 / “Human Verification”, measured 2026-10-19
 *
 * No metadata is invented: titles, dates, creators, institutions, rights and
 * links are copied from the upstream JSON; records without a machine-readable
 * footprint keep *no* extent instead of a guessed one, so the map never places
 * them at an invented coordinate.
 *
 * Usage:
 *   node scripts/fetch-world-records.mjs                 # fetch, merge, write
 *   node scripts/fetch-world-records.mjs --offline       # replay .cache/world/
 *   node scripts/fetch-world-records.mjs --dry-run       # print, write nothing
 *   node scripts/fetch-world-records.mjs --per-query 2   # max records per query
 *
 * The script is dependency-free, identifies itself, caches every upstream
 * response under `.cache/world/` (git-ignored) and never writes outside
 * `public/data/`.
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const UA = 'Kartenzeit/1.0 (independent historical-map study; contact: project maintainers)';
const RETRIEVED = '2026-10-19';
const CACHE_DIR = new URL('../.cache/world/', import.meta.url);
const args = process.argv.slice(2);
const OFFLINE = args.includes('--offline');
const DRY_RUN = args.includes('--dry-run');
const PER_QUERY = Number(getArg('--per-query') || 2);
const LIMIT = Number(getArg('--limit') || 0);

function getArg(name) {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : null;
}

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

function cacheFile(url, as) {
  const hash = createHash('sha1').update(url).digest('hex').slice(0, 20);
  return new URL(`./${hash}.${as === 'json' ? 'json' : 'txt'}`, CACHE_DIR);
}

/** Polite GET with an on-disk cache, bounded retries and a descriptive UA. */
async function get(url, { as = 'json', timeout = 25000, attempts = 3 } = {}) {
  const file = cacheFile(url, as);
  if (OFFLINE) {
    const cached = await readFile(file, 'utf8');
    return as === 'json' ? JSON.parse(cached) : cached;
  }
  for (let attempt = 1; ; attempt += 1) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeout);
    try {
      const res = await fetch(url, {
        headers: { 'user-agent': UA, accept: as === 'json' ? 'application/json' : '*/*' },
        signal: ctrl.signal,
        redirect: 'follow',
      });
      if (!res.ok) {
        if ((res.status === 429 || res.status >= 500) && attempt < attempts) {
          await sleep(attempt * 1500);
          continue;
        }
        const err = new Error(`${res.status} ${url}`);
        err.status = res.status;
        throw err;
      }
      const body = as === 'json' ? await res.json() : await res.text();
      await mkdir(CACHE_DIR, { recursive: true });
      await writeFile(file, as === 'json' ? JSON.stringify(body) : body);
      return body;
    } catch (err) {
      if (err.name === 'AbortError' && attempt < attempts) {
        await sleep(attempt * 1500);
        continue;
      }
      throw err;
    } finally {
      clearTimeout(timer);
    }
  }
}

/* ------------------------------------------------------------------ *
 * small, pure helpers (unit-tested through tests/world-records.test.mjs)
 * ------------------------------------------------------------------ */

const FOUR_DIGIT = /(1[5-9]\d{2}|20[0-2]\d)/;

/** The first plausible publication year in an upstream date string, or null. */
export function parseUpstreamYear(value) {
  const text = Array.isArray(value) ? value.find(Boolean) : value;
  if (typeof text !== 'string') return null;
  const match = FOUR_DIGIT.exec(text);
  if (!match) return null;
  const year = Number(match[1]);
  return year >= 1500 && year <= 2025 ? year : null;
}

/** "United States. Central Intelligence Agency" → the string unchanged; only trims. */
export function cleanText(value) {
  if (value == null) return null;
  const text = Array.isArray(value) ? value.find((v) => typeof v === 'string' && v.trim()) : String(value);
  if (typeof text !== 'string') return null;
  const trimmed = text.replace(/\s+/g, ' ').trim();
  return trimmed || null;
}

/** Title-case a lower-case upstream label ("general maps" → "General Maps"). */
export function titleCase(label) {
  const text = cleanText(label);
  if (!text) return null;
  return text
    .split(' ')
    .map((word) => (/^[a-zà-ÿ]/.test(word) ? word[0].toUpperCase() + word.slice(1) : word))
    .join(' ');
}

/** The LoC lccn from an item URL like http://www.loc.gov/item/2009580101/. */
export function lccnFromUrl(value) {
  const text = cleanText(value);
  if (!text) return null;
  const match = /loc\.gov\/(?:item\/)?([A-Za-z0-9._-]+)\/?$/.exec(text.replace(/[#?].*$/, ''));
  return match ? match[1] : null;
}

/** The IIIF image service id inside a tile.loc.gov image URL. */
export function imageServiceFromUrl(value) {
  const text = cleanText(value);
  if (!text) return null;
  const match = /^(https:\/\/tile\.loc\.gov\/image-services\/iiif\/[^/]+)\//.exec(text);
  return match ? match[1] : null;
}

/** Pick the smallest usable IIIF derivative from LoC's image_url list. */
export function pickLocImage(images) {
  const list = (Array.isArray(images) ? images : []).map((u) => cleanText(u)).filter(Boolean);
  const iiif = list.filter((u) => u.includes('/image-services/iiif/') && !u.includes('/full/full/'));
  const preferred = iiif.find((u) => /\/full\/pct:12\.5\/0\/default\.jpg$/.test(u.split('#')[0]))
    || iiif.find((u) => /\/full\/pct:25\/0\/default\.jpg$/.test(u.split('#')[0]))
    || iiif[0];
  if (preferred) return preferred.split('#')[0];
  return list.find((u) => /\.(jpg|jpeg|png)$/i.test(u.split('#')[0]))?.split('#')[0] ?? null;
}

/* ------------------------------------------------------------------ *
 * provider definitions
 * ------------------------------------------------------------------ */

/**
