    id: `loc:${lccn}`,
    title,
    yearStart: year,
    yearEnd: year,
    depictedYearStart: null,
    depictedYearEnd: null,
    creators: (item.contributors ?? result.contributor ?? []).map(cleanText).filter(Boolean),
    providerId: 'loc',
    institution: 'Library of Congress. Geography and Map Division',
    // Verbatim upstream rights policy (plain-text form of the JSON `rights` HTML).
    rights: 'Free to use and reuse; credit: Library of Congress, Geography and Map Division.',
    recordUrl: `https://www.loc.gov/item/${lccn}/`,
    thumbnail: image,
    type: 'map',
