    ...(places.length ? { subjectPlace: places[0], subjectPlaces: places } : {}),
    ...(item.call_number?.[0] ? { shelfmark: cleanText(item.call_number[0]) } : {}),
    ...(item.created_published?.[0] ? { imprint: cleanText(item.created_published[0]) } : {}),
    ...(item.language?.[0] ? { language: cleanText(item.language[0]) } : {}),
    imageService: imageServiceFromUrl(image),
    rightsUrl: 'https://www.loc.gov/legal/',
    dateKind: 'publication',
    harvestedBy: 'scripts/fetch-world-records.mjs',
    // No `extent`: the LoC JSON search does not publish a machine-readable
    // footprint for these records, so none is invented.
  };
}

/** Field values of one Luna search result as a flat label → values map. */
export function rumseyFields(result) {
  const out = {};
  for (const group of result?.fieldValues ?? []) {
    for (const [key, value] of Object.entries(group ?? {})) {
      const list = (Array.isArray(value) ? value : [value]).map(cleanText).filter(Boolean);
      if (list.length) out[key] = [...(out[key] ?? []), ...list];
    }
  }
  return out;
}

/** Turn one Luna search result into a seed record, or null. */
export function rumseyResultToRecord(result) {
  const id = cleanText(result?.id);
  const fields = rumseyFields(result);
  const title = cleanText(result?.displayName) ?? cleanText(fields['Full Title']?.[0]);
  const year = parseUpstreamYear(fields.Date) ?? parseUpstreamYear(fields['Pub Date']);
  const image = cleanText(result?.urlSize2) ?? cleanText(result?.urlSize1);
  if (!id || !title || year == null || !image || year > 1930) return null;
  const place = cleanText(fields.Where?.[0]) ?? cleanText(fields.Country?.[0]) ?? cleanText(fields.Region?.[0]);
  const creators = fields.Author ?? fields['Publication Author'] ?? [];
  return {
    id: `rumsey:${id}`,
    title,
    yearStart: year,
    yearEnd: year,
    depictedYearStart: null,
    depictedYearEnd: null,
    creators,
    providerId: 'rumsey',
    institution: 'David Rumsey Map Collection, David Rumsey Map Center, Stanford University Libraries',
    rights:
      'Images: CC BY-NC-SA 3.0 (David Rumsey Map Collection); the map’s own copyright status is stated by the record.',
    recordUrl: `https://www.davidrumsey.com/luna/servlet/detail/${id}`,
    thumbnail: image,
    type: 'map',
    collection: 'David Rumsey Map Collection',
    ...(place ? { subjectPlace: place } : {}),
    ...(fields['Short Title']?.[0] && fields['Short Title'][0] !== title ? { titleAlt: [fields['Short Title'][0]] } : {}),
    ...(fields.Publisher?.[0] ? { publisher: fields.Publisher[0] } : {}),
    ...(fields['Pub Title']?.[0] ? { imprint: fields['Pub Title'][0] } : {}),
    ...(fields['List No']?.[0] ? { shelfmark: `List No. ${fields['List No'][0]}` } : {}),
    ...(fields['Pub Reference']?.[0] ? { note: fields['Pub Reference'][0] } : {}),
    viewerUrl: `https://www.davidrumsey.com/luna/servlet/detail/${id}`,
    rightsUrl: 'https://www.davidrumsey.com/about/copyright-and-permissions',
    dateKind: 'publication',
    harvestedBy: 'scripts/fetch-world-records.mjs',
    // No `iiifManifest`: the image service needs a browser session; the record
    // links to the original instead of promising an embedded deep zoom.
  };
}

/** LoC search URL for one query (documented `fo=json` API). */
export function locSearchUrl(query, count = 10) {
  const url = new URL('https://www.loc.gov/maps/');
  url.searchParams.set('q', query);
  url.searchParams.set('fo', 'json');
  url.searchParams.set('c', String(count));
  return url.toString();
}

/** Luna search URL for one query. */
export function rumseySearchUrl(query, count = 5) {
  const url = new URL('https://www.davidrumsey.com/luna/servlet/as/search');
  url.searchParams.set('q', query);
  url.searchParams.set('os', '0');
  url.searchParams.set('bs', String(count));
  return url.toString();
}

/* ------------------------------------------------------------------ *
 * harvest
 * ------------------------------------------------------------------ */

/** Keep the first `perQuery` results per query that produced a record. */
function pickPerQuery(candidates, perQuery) {
  const perGroup = new Map();
  const out = [];
  for (const c of candidates) {
    const n = perGroup.get(c.group) ?? 0;
    if (n >= perQuery) continue;
    perGroup.set(c.group, n + 1);
    out.push(c);
  }
  return out;
}

async function harvestLoc(perQuery) {
  const candidates = [];
  const considered = [];
  for (const { id, q } of LOC_QUERIES) {
    let payload;
    try {
      payload = await get(locSearchUrl(q, 12));
    } catch (err) {
      considered.push({ query: q, group: id, error: String(err.message || err) });
      continue;
    }
    const results = payload?.content?.results ?? payload?.results ?? [];
    const usable = results
      .map((r) => locResultToRecord(r))
      .filter(Boolean)
      .sort((a, b) => a.yearStart - b.yearStart);
    considered.push({ query: q, group: id, results: results.length, usable: usable.length });
    for (const record of usable) candidates.push({ group: id, record });
  }
  return { records: pickPerQuery(candidates, perQuery).map((c) => c.record), considered };
}

async function harvestRumsey(perQuery) {
  const candidates = [];
  const considered = [];
  for (const { id, q } of RUMSEY_QUERIES) {
    let payload;
    try {
      payload = await get(rumseySearchUrl(q, 8));
    } catch (err) {
      considered.push({ query: q, group: id, error: String(err.message || err) });
      continue;
    }
    const results = payload?.results ?? [];
    const usable = results
      .map((r) => rumseyResultToRecord(r))
      .filter(Boolean)
      .sort((a, b) => a.yearStart - b.yearStart);
    considered.push({ query: q, group: id, results: results.length, usable: usable.length });
    for (const record of usable) candidates.push({ group: id, record });
  }
  return { records: pickPerQuery(candidates, perQuery).map((c) => c.record), considered };
}

/**
 * Probe the two sources the brief named that this runner cannot read. The
 * result is recorded in the registry (`worldHarvest.probes`) so a later
 * iteration can retry instead of rediscovering the block.
 */
async function probeBlockedSources() {
  const probes = [];
  for (const [name, url] of [
    ['BnF Gallica SRU', 'https://gallica.bnf.fr/SRU?operation=searchRetrieve&version=1.2&query=gallica%20all%20%22plan%20de%20paris%22&maximumRecords=1'],
    ['National Library of Scotland', 'https://maps.nls.uk/'],
  ]) {
    if (OFFLINE) {
      probes.push({ name, url, status: 'not probed offline', measured: RETRIEVED, retry: true });
      continue;
    }
    try {
      const res = await fetch(url, { headers: { 'user-agent': UA }, signal: AbortSignal.timeout(15000) });
      probes.push({
        name,
        url,
        status: res.status,
        measured: RETRIEVED,
        retry: !res.ok,
        note:
          res.ok
            ? 'reachable now — a later harvest can add this provider'
            : 'blocked from this runner (bot challenge / not a documented API); recorded so the registry stays honest',
      });
    } catch (err) {
      probes.push({ name, url, status: 'network error', detail: String(err.message || err).slice(0, 120), measured: RETRIEVED, retry: true });
    }
  }
  return probes;
}

async function readJson(path) {
  return JSON.parse(await readFile(path, 'utf8'));
}

async function main() {
  const [loc, rumsey, probes] = await Promise.all([harvestLoc(PER_QUERY), harvestRumsey(PER_QUERY), probeBlockedSources()]);
  let records = [...loc.records, ...rumsey.records];
  if (LIMIT > 0) records = records.slice(0, LIMIT);

  const perProvider = {
    loc: records.filter((r) => r.providerId === 'loc').length,
    rumsey: records.filter((r) => r.providerId === 'rumsey').length,
  };
  const years = records.map((r) => r.yearStart);
  console.log(
    `World harvest: ${records.length} records (${perProvider.loc} LoC, ${perProvider.rumsey} Rumsey), ` +
      `${years.length ? `${Math.min(...years)}–${Math.max(...years)}` : 'no years'}, ` +
      `${records.filter((r) => !r.extent).length} without an invented footprint`,
  );

  if (DRY_RUN) {
    console.log(JSON.stringify(records.slice(0, 3), null, 2));
    return;
  }

  const outDir = resolve(fileURLToPath(new URL('../public/data/', import.meta.url)));
  const recordsDoc = await readJson(resolve(outDir, 'records.json'));
  const sourcesDoc = await readJson(resolve(outDir, 'sources.json'));

  const keptExisting = recordsDoc.records.filter((r) => !r.id.startsWith('loc:') && !r.id.startsWith('rumsey:'));
  const merged = [...keptExisting, ...records];
  const seen = new Set();
  recordsDoc.records = merged.filter((r) => (seen.has(r.id) ? false : (seen.add(r.id), true)));
  recordsDoc.worldHarvest = {
    retrieved: RETRIEVED,
    script: 'scripts/fetch-world-records.mjs',
    notes: 'LoC + Rumsey records merged into this file; run scripts/fetch-records.mjs first, then this script to refresh both.',
    loc: { queries: loc.considered },
    rumsey: { queries: rumsey.considered },
    probes,
  };

  const replaceProvider = (entry) => {
    const index = sourcesDoc.providers.findIndex((p) => p.id === entry.id);
    if (index >= 0) sourcesDoc.providers[index] = entry;
    else sourcesDoc.providers.push(entry);
  };
  replaceProvider({
    ...PROVIDERS.loc,
    harvest: { queries: loc.considered, kept: perProvider.loc, simplification: 'none' },
  });
  replaceProvider({
    ...PROVIDERS.rumsey,
    harvest: { queries: rumsey.considered, kept: perProvider.rumsey, simplification: 'none' },
  });
  sourcesDoc.worldHarvest = { retrieved: RETRIEVED, probes, method: 'documented JSON/IIIF services, merged with scripts/fetch-world-records.mjs' };
  sourcesDoc.generatedAt = new Date().toISOString();

  await writeFile(resolve(outDir, 'records.json'), JSON.stringify(recordsDoc, null, 2) + '\n');
  await writeFile(resolve(outDir, 'sources.json'), JSON.stringify(sourcesDoc, null, 2) + '\n');
  console.log(`Wrote ${recordsDoc.records.length} records and ${sourcesDoc.providers.length} providers to ${outDir}`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}

