/**
 * Worldwide provider coverage (correction 1 of the 2026-10-19 brief).
 *
 * The corrected product is a global English atlas, so the seed must hold real
 * archival records from outside Switzerland, read from documented primary
 * services and attributed to their holding institution. These tests run offline
 * against the committed seed plus pure fixtures for the harvest adapters.
 *
 * Owner: zurich-maps-0 (`scripts/fetch-world-records.mjs`).
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';

import { matchesQuery } from '../public/app/records.js';
import {
  cleanText,
  imageServiceFromUrl,
  lccnFromUrl,
  locResultToRecord,
  parseUpstreamYear,
  pickLocImage,
  rumseyResultToRecord,
  titleCase,
} from '../scripts/fetch-world-records.mjs';

const root = new URL('..', import.meta.url);
const readJson = async (rel) => JSON.parse(await readFile(new URL(rel, root), 'utf8'));

const recordsDoc = await readJson('public/data/records.json');
const sourcesDoc = await readJson('public/data/sources.json');
const records = recordsDoc.records;
const worldRecords = records.filter((r) => r.providerId === 'loc' || r.providerId === 'rumsey');
const providerById = new Map(sourcesDoc.providers.map((p) => [p.id, p]));

/* ------------------------------------------------------------------ *
 * adapters (pure, fixture-driven)
 * ------------------------------------------------------------------ */

test('parseUpstreamYear reads the first plausible publication year', () => {
  assert.equal(parseUpstreamYear('1925'), 1925);
  assert.equal(parseUpstreamYear('[1898?]'), 1898);
  assert.equal(parseUpstreamYear('ca. 1700'), 1700);
  assert.equal(parseUpstreamYear(['1815', '1817']), 1815);
  assert.equal(parseUpstreamYear('200?'), null, 'incomplete years are dropped, not guessed');
  assert.equal(parseUpstreamYear('9999-01-01'), null);
  assert.equal(parseUpstreamYear(''), null);
  assert.equal(parseUpstreamYear(null), null);
});

test('lccnFromUrl and imageServiceFromUrl read only documented URL shapes', () => {
  assert.equal(lccnFromUrl('http://www.loc.gov/item/2009580101/'), '2009580101');
  assert.equal(lccnFromUrl('https://www.loc.gov/item/00556401/#item'), '00556401');
  assert.equal(lccnFromUrl('https://example.org/nope'), null);
  assert.equal(
    imageServiceFromUrl('https://tile.loc.gov/image-services/iiif/service:gmd:gmd8:g8304:g8304c:ct002477/full/pct:12.5/0/default.jpg'),
    'https://tile.loc.gov/image-services/iiif/service:gmd:gmd8:g8304:g8304c:ct002477',
  );
  assert.equal(imageServiceFromUrl('https://www.davidrumsey.com/x.jpg'), null);
});

test('pickLocImage prefers a small IIIF derivative and never returns a fragment', () => {
  const images = [
    'https://tile.loc.gov/storage-services/service/gmd/g8304/ct002477.gif#h=150&w=173',
    'https://tile.loc.gov/image-services/iiif/service:gmd:g8304:ct002477/full/pct:25/0/default.jpg#h=2689&w=3094',
    'https://tile.loc.gov/image-services/iiif/service:gmd:g8304:ct002477/full/pct:12.5/0/default.jpg#h=1344&w=1547',
  ];
  assert.equal(
    pickLocImage(images),
    'https://tile.loc.gov/image-services/iiif/service:gmd:g8304:ct002477/full/pct:12.5/0/default.jpg',
  );
  assert.equal(pickLocImage(['https://tile.loc.gov/a.gif']), 'https://tile.loc.gov/a.gif');
  assert.equal(pickLocImage([]), null);
});

test('cleanText and titleCase keep upstream wording, only trimmed and titled', () => {
  assert.equal(cleanText('  Cairo & environs  '), 'Cairo & environs');
  assert.equal(cleanText(['', 'General maps']), 'General maps');
  assert.equal(titleCase('general maps'), 'General maps');
  assert.equal(titleCase('south america'), 'South america');
});

test('a LoC result becomes a record only with lccn, year, image and no restriction', () => {
  const base = {
    id: 'http://www.loc.gov/item/2009580101/',
    title: 'Cairo & environs',
    date: '1925',
    image_url: ['https://tile.loc.gov/image-services/iiif/service:gmd:g8304:ct002477/full/pct:12.5/0/default.jpg'],
    item: { contributors: ['Egypt. Maṣlaḥat al-Misāḥah'], location: ['Cairo Region (Egypt)'] },
    access_restricted: false,
  };
  const record = locResultToRecord(base);
  assert.equal(record.id, 'loc:2009580101');
  assert.equal(record.providerId, 'loc');
  assert.equal(record.yearStart, 1925);
  assert.equal(record.recordUrl, 'https://www.loc.gov/item/2009580101/');
  assert.equal(record.subjectPlace, 'Cairo Region (Egypt)');
  assert.equal(record.extent, undefined, 'no machine-readable footprint in the service → no invented bbox');
  assert.equal(locResultToRecord({ ...base, access_restricted: true }), null);
  assert.equal(locResultToRecord({ ...base, date: '200?' }), null);
  assert.equal(locResultToRecord({ ...base, image_url: [] }), null);
  assert.equal(locResultToRecord({ ...base, title: 'Text: something' }), null, 'text pages are not map imagery');
});

test('a Rumsey result becomes a record only when it is an image with a pre-1931 date', () => {
  const base = {
    id: 'RUMSEY~8~1~292700~90064061',
    displayName: 'Africa, North Part',
    mediaType: 'Image',
    urlSize2: 'https://www.davidrumsey.com/rumsey/Size2/RUMSEY~8~1/162/292700.jpg',
    fieldValues: [
      { Date: ['1841'] },
      { Author: ['Black, Adam'] },
      { Type: ['Atlas Map'] },
      { Where: ['Africa'] },
    ],
  };
  const record = rumseyResultToRecord(base);
  assert.equal(record.id, 'rumsey:RUMSEY~8~1~292700~90064061');
  assert.equal(record.providerId, 'rumsey');
  assert.equal(record.yearStart, 1841);
  assert.equal(record.creators[0], 'Black, Adam');
  assert.equal(record.extent, undefined, 'no footprint is claimed and none is invented');
  assert.ok(record.rights.includes('CC BY-NC-SA'), 'the collection’s image licence is stated');
  assert.equal(rumseyResultToRecord({ ...base, mediaType: 'Text' }), null);
  assert.equal(rumseyResultToRecord({ ...base, fieldValues: [{ Date: ['1941'] }, { Type: ['Atlas Map'] }] }), null);
  assert.equal(
    rumseyResultToRecord({ ...base, displayName: 'Title: some atlas title page' }),
    null,
    'title pages are not map imagery',
  );
});

/* ------------------------------------------------------------------ *
 * the committed seed
 * ------------------------------------------------------------------ */

test('the seed carries worldwide records from the two documented providers', () => {
  assert.ok(worldRecords.length >= 24, `expected a usable worldwide set, found ${worldRecords.length}`);
  const byProvider = {
    loc: worldRecords.filter((r) => r.providerId === 'loc').length,
    rumsey: worldRecords.filter((r) => r.providerId === 'rumsey').length,
  };
  assert.ok(byProvider.loc >= 10, `Library of Congress records: ${byProvider.loc}`);
  assert.ok(byProvider.rumsey >= 10, `David Rumsey records: ${byProvider.rumsey}`);
});

test('both worldwide providers are documented with rights, attribution and hosts', () => {
  for (const id of ['loc', 'rumsey']) {
    const provider = providerById.get(id);
    assert.ok(provider, `${id}: provider entry missing from sources.json`);
    assert.ok(provider.name && provider.homepage?.startsWith('https://'), `${id}: name/homepage`);
    assert.ok(provider.rights && provider.rights.length > 20, `${id}: rights statement`);
    assert.ok(provider.attribution && provider.attribution.length > 5, `${id}: attribution`);
    assert.ok(provider.api && Object.keys(provider.api).length > 0, `${id}: documented api endpoints`);
    assert.ok(Array.isArray(provider.apiHosts) && provider.apiHosts.length > 0, `${id}: apiHosts`);
    assert.ok(provider.retrievalDate, `${id}: retrievalDate`);
    assert.ok(provider.notes, `${id}: notes state what the harvest measured`);
  }
});

test('every worldwide record points at its institution on a documented host', () => {
  const ids = new Set();
  for (const record of worldRecords) {
    const provider = providerById.get(record.providerId);
    const hosts = new Set(provider.apiHosts);
    const hostOf = (url) => new URL(url).hostname;
    assert.ok(!ids.has(record.id), `${record.id}: duplicate`);
    ids.add(record.id);
    assert.ok(!/oldmapsonline\.org/.test(record.recordUrl), `${record.id}: no aggregator as the source`);
    assert.ok(hosts.has(hostOf(record.recordUrl)), `${record.id}: recordUrl host ${hostOf(record.recordUrl)}`);
    assert.ok(hosts.has(hostOf(record.thumbnail)), `${record.id}: thumbnail host ${hostOf(record.thumbnail)}`);
    assert.equal(record.harvestedBy, 'scripts/fetch-world-records.mjs', `${record.id}: documented harvest path`);
    assert.equal(record.dateKind, 'publication', `${record.id}: publication date is labelled as such`);
    assert.ok(Number.isInteger(record.yearStart) && record.yearStart <= record.yearEnd, `${record.id}: years`);
    assert.ok(record.title.length > 2 && record.rights.length > 10, `${record.id}: title/rights`);
    assert.equal(record.extent, undefined, `${record.id}: no footprint is claimed by these services`);
    assert.equal(record.geo, undefined, `${record.id}: no point is invented`);
  }
});

test('the worldwide set spans continents, not one city', () => {
  const textOf = (record) =>
    [record.subjectPlace, ...(record.subjectPlaces ?? []), record.title, record.collection]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
  const groups = {
    Africa: /africa/,
    Asia: /asia|japan|china|india|middle east|islamic world|tokyo|edo/,
    Americas: /america|mexico|brazil|paulo|canada|chile|peru/,
    Europe: /europe|britain|france|germany|italy|spain/,
    Oceania: /australia|zealand|oceania/,
  };
  for (const [group, pattern] of Object.entries(groups)) {
    const hits = worldRecords.filter((r) => pattern.test(textOf(r)));
    assert.ok(hits.length >= 3, `${group}: expected 3+ worldwide records, found ${hits.length}`);
  }
});

test('the worldwide set reaches early and modern publication years', () => {
  const years = worldRecords.map((r) => r.yearStart).sort((a, b) => a - b);
  assert.ok(years[0] <= 1700, `an early sheet is present (earliest ${years[0]})`);
  assert.ok(years[years.length - 1] >= 1900, `a modern sheet is present (latest ${years[years.length - 1]})`);
  assert.ok(worldRecords.filter((r) => r.yearStart < 1800).length >= 5, 'several 16th–18th century sheets');
});

test('places outside Switzerland are findable in the seed keyword search', () => {
  for (const query of ['Cairo', 'Tokyo', 'Mexico City', 'São Paulo', 'São Paulo'.normalize('NFD').replace(/[\u0300-\u036f]/g, '')]) {
    const hits = records.filter((r) => matchesQuery(r, query));
    assert.ok(hits.length > 0, `“${query}” must find worldwide records`);
    assert.ok(
      hits.some((r) => r.providerId === 'loc' || r.providerId === 'rumsey'),
      `“${query}” must reach a worldwide provider, not only e-rara`,
    );
  }
});

